using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Train the model at startup and register the pooled prediction engine.
builder.Services.AddSingleton<TicketModelTrainer>();
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>();

var app = builder.Build();

// Train once at startup so the model file exists before requests arrive.
var trainer = app.Services.GetRequiredService<TicketModelTrainer>();
trainer.TrainAndEvaluate();

// Configure the prediction engine pool to load from the trained model file.
app.Services.GetRequiredService<PredictionEnginePoolBuilder<TicketInput, TicketPrediction>>()
    .FromFile(modelName: null, filePath: trainer.ModelPath, watchForChanges: false);

app.MapControllers();
app.Run();

